function validate([n, edges, t, target]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  if (!Number.isInteger(t) || t < 1 || t > 50) return 't is between 1 and 50.';
  if (!Number.isInteger(target) || target < 1 || target > n) return 'target is a vertex from 1 to n.';
  const root = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || a > n || b < 1 || b > n) return 'Edge endpoints are vertices from 1 to n.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  return null;
}

