function frogPosition(n, edges, t, target) {
  const graph = Array.from({ length: n + 1 }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const dfs = (vertex, parent, time) => {
    const children = graph[vertex].length - (parent === 0 ? 0 : 1);
    if (vertex === target) {
      return time === t || children === 0 ? 1 : 0;
    }
    if (time === t) {
      return 0;
    }
    for (const next of graph[vertex]) {
      if (next === parent) continue;
      const found = dfs(next, vertex, time + 1);
      if (found > 0) {
        return found / children;
      }
    }
    return 0;
  };

  return dfs(1, 0, 0);
}

