function frogPosition(n, edges, t, target) {
  // Forward simulation: push the whole probability distribution one second at a time.
  const adjacent = Array.from({ length: n + 1 }, () => []);
  edges.forEach(([a, b]) => { adjacent[a].push(b); adjacent[b].push(a); });
  const up = new Array(n + 1).fill(-1);
  up[1] = 0;
  const order = [1];
  for (let k = 0; k < order.length; k++) for (const w of adjacent[order[k]]) if (up[w] === -1) { up[w] = order[k]; order.push(w); }
  let chance = new Array(n + 1).fill(0);
  chance[1] = 1;
  for (let second = 0; second < t; second++) {
    const after = new Array(n + 1).fill(0);
    for (let v = 1; v <= n; v++) {
      if (chance[v] === 0) continue;
      const kids = adjacent[v].filter(w => w !== up[v]);
      if (kids.length === 0) after[v] += chance[v];
      else kids.forEach(w => { after[w] += chance[v] / kids.length; });
    }
    chance = after;
  }
  return chance[target];
}

