function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(60, 100) : int(1, 8);
  const shape = rand();
  // Build a tree on positions 0..n-1 where each position hangs below an earlier one.
  const parentOf = [-1];
  for (let i = 1; i < n; i++) {
    if (shape < 0.2) parentOf.push(i - 1);
    else if (shape < 0.35) parentOf.push(0);
    else if (shape < 0.6) parentOf.push(Math.max(0, i - int(1, 3)));
    else parentOf.push(int(0, i - 1));
  }
  // Relabel with a random permutation; any vertex may become label 1.
  const labels = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [labels[i], labels[j]] = [labels[j], labels[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push(rand() < 0.5 ? [labels[i], labels[parentOf[i]]] : [labels[parentOf[i]], labels[i]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const t = size === 'large' ? int(1, 50) : int(1, 6);
  // Bias the target toward vertices at distance about t from vertex 1 so non-zero answers are common.
  const adjacent = Array.from({ length: n + 1 }, () => []);
  edges.forEach(([a, b]) => { adjacent[a].push(b); adjacent[b].push(a); });
  const depth = new Array(n + 1).fill(-1);
  depth[1] = 0;
  const order = [1];
  for (let k = 0; k < order.length; k++) for (const w of adjacent[order[k]]) if (depth[w] === -1) { depth[w] = depth[order[k]] + 1; order.push(w); }
  let target = int(1, n);
  if (rand() < 0.6) {
    const near = order.filter(v => depth[v] === t || (depth[v] < t && adjacent[v].length === (v === 1 ? 0 : 1)));
    if (near.length) target = near[int(0, near.length - 1)];
  }
  return [n, edges, t, target];
}
